def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: int or str representing the number of nanoseconds since the Unix epoch.
    :param tz: timezone object or str representing the timezone.
    :return: datetime object
    """
    if isinstance(nanoseconds, str):
        nanoseconds = int(nanoseconds)

    if tz is None:
        dt = datetime.fromtimestamp(nanoseconds / 1_000_000_000, tz=timezone.utc)
    elif isinstance(tz, str):
        tz = timezone.utc if tz.lower() == 'utc' else tz  # Placeholder for timezone interpretation
        dt = datetime.fromtimestamp(nanoseconds / 1_000_000_000, tz=tz)
    elif isinstance(tz, timezone):
        dt = datetime.fromtimestamp(nanoseconds / 1_000_000_000, tz=tz)
    else:
        raise ValueError("Invalid timezone provided")

    return dt

