import threading

def cached(cache, key=None, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    def decorator(func):
        if key is None:
            def _key(*args, **kwargs):
                return hash(args) ^ hash(tuple(sorted(kwargs.items())))
        else:
            _key = key

        if lock is None:
            lock = threading.Lock()

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal cache
            result = cache.get(_key(*args, **kwargs))
            if result is None:
                with lock:
                    if _key(*args, **kwargs) not in cache:
                        result = func(*args, **kwargs)
                        cache[_key(*args, **kwargs)] = result
            return result

        return wrapper

    return decorator

