class ValidationError(Exception):
    def __init__(self, messages):
        super().__init__(messages)
        self.messages = messages

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    for key, value in labels.items():
        if key is not None and not isinstance(key, str) and isinstance(key, (list, tuple, dict)):
            errors.append({repr(key): 'expected string or bytes-like object'})
        if not isinstance(key, str):
            errors.append({repr(key): 'expected string or bytes-like object'})

        if not key:
            errors.append({repr(key): 'Label key cannot be empty'})

        if key and isinstance(key, str) and not re.match(r'^[a-zA-Z0-9-_:@]+$', key):
            errors.append({repr(key): "Label key does not match the regex ^[a-zA-Z0-9-_:@]+$"})

        if value is not None and not isinstance(value, (str, bytes, bytearray)):
            errors.append({repr(value): 'expected string or bytes-like object'})
        if isinstance(value, (list, tuple, dict)):
            for item in value:
                if not isinstance(item, (str, bytes, bytearray)):
                    errors.append({repr(item): 'expected string or bytes-like object'})

        if not isinstance(value, str):
            errors.append({repr(value): 'expected string or bytes-like object'})

        if value and isinstance(value, str) and not re.match(r'^[a-zA-Z0-9-_:@.]+$', value):
            errors.append({repr(value): "Label value does not match the regex ^[a-zA-Z0-9-_:@.]+$"})

    if errors:
        raise ValidationError(errors)

