def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: Dictionary of manifest files with their required digests
    :param digests_used: List of digests that have been used
    :return: None
    """
    for manifest_file, required_digests in manifest_files.items():
        for digest in required_digests:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} required for {manifest_file} is not present.")
