def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    allowed_files = {os.path.basename(manifest_file) for manifest_file in manifest_files}

    for file_info in fixity.getchildren():
        file_name = file_info.get('filename')
        if not file_name or file_name not in allowed_files:
            raise ValueError(f"Invalid file reference in fixity block: {file_name}")

