from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet or not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Alphabet must be a non-empty list of strings.")

    if number < 0:
        raise ValueError("Number must be non-negative.")

    if not alphabet:
        raise ValueError("Alphabet must not be empty.")

    digits = []
    base = len(alphabet)

    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    if not digits:
        digits.append(alphabet[0])

    result = ''.join(digits[::-1])

    if padding is not None and padding > len(result):
        result = result.zfill(padding)

    return result

