import collections

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.freq = collections.OrderedDict()
        self.count = {}

    def _increase_frequency(self, key):
        self.count[key] += 1
        f = self.count[key]
        self.freq[f].add(key)
        if f > 1:
            self.freq[f - 1].remove(key)
            if not self.freq[f - 1]:
                del self.freq[f - 1]

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        self._increase_frequency(key)
        return self.cache[key]

    def set(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = value
            self._increase_frequency(key)
        else:
            if len(self.cache) == self.capacity:
                _, k = self.freq[min(self.freq)].popitem(last=False)
                if not self.freq[min(self.freq)]:
                    del self.freq[min(self.freq)]
                del self.cache[k]
                del self.count[k]
            self.cache[key] = value
            self.freq[1].add(key)
            self.count[key] = 1

    def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self.cache:
            raise KeyError('popitem(): cache is empty')

        if not self.freq:
            raise KeyError('popitem(): cache is empty')

        key = self.freq[min(self.freq)].popitem(last=False)[1]
        value = self.cache[key]

        if not self.freq[min(self.freq)]:
            del self.freq[min(self.freq)]

        del self.cache[key]
        del self.count[key]

        return (key, value)

