def parse_xrd(xrd_string: str) -> Dict:
    """
    Parses XRD (eXtensible Resource Descriptor) format.

    Parameters:
        xrd_string (str): The XRD document as a string.

    Returns:
        Dict: Parsed XRD data.
    """
    # This is a simplified example. In a real-world scenario, you would need to use an XML parser
    xrd_dict = {}
    for line in xrd_string.split('\n'):
        if '<Link' in line:
            # Extract attributes from the Link tag
            attributes = {}
            for attr in line.split(' '):
                if '=' in attr:
                    key, value = attr.split('=')
                    attributes[key.strip('"')] = value.strip('"')
            xrd_dict.update(attributes)
    return xrd_dict

