import argparse

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Define type conversions based on parser name
    type_conversions = {
        'main': {
            'int_arg': int,
            'float_arg': float,
            'bool_arg': lambda x: x.lower() in ['true', '1', 't', 'y', 'yes']
        },
        'virsh': {
            'host_arg': str,
            'port_arg': int
        },
        'ospd': {
            'timeout_arg': int,
            'debug_arg': lambda x: x.lower() in ['true', '1', 't', 'y', 'yes']
        }
    }

    # Apply type conversions to values_dict
    if parser_name in type_conversions:
        for key, value in type_conversions[parser_name].items():
            if key in values_dict:
                values_dict[key] = value(values_dict[key])

